from dataclasses import dataclass
from typing import Dict, Any

@dataclass
class ArchiveRecord:
    id: str
    title: str
    metadata: Dict[str, Any]


def index_record(record: ArchiveRecord) -> dict:
    # normalize and index metadata fields for search
    normalized = {k.lower(): v for k, v in record.metadata.items()}
    return {"id": record.id, "title": record.title, "index": normalized}

type Meta = Record<string, unknown>

const aliases: Record<string, string> = {
  "doc_type": "document_type",
  "doctype": "document_type",
  "createdon": "created_at"
}

export function normalizeMetadata(meta: Meta): Meta {
  return Object.fromEntries(
    Object.entries(meta).map(([k, v]) => [aliases[k.toLowerCase()] ?? k.toLowerCase(), v])
  )
}
